/* Deposit into an Arc lending vault, and take it back out, from the visitor's OWN wallet (2026-10-07).
 * The page (generated by tools/arc-yield.js) sets window.EARN_VAULTS = [{a, n, c, out, apy, warn, verdict}] (USDC vaults that
 * Circle Earn Kit lists on Arc, read on chain) and window.EARN_ON (deposits/withdrawals switched on after review).
 * Rules this file keeps:
 *   - the receiver and owner of every deposit and redeem is the connected wallet, read once from eth_requestAccounts and shown;
 *     no field, URL or server value can change it;
 *   - only vaults in EARN_VAULTS can be used; USDC is Arc's ERC-20 face 0x3600... (6 decimals);
 *   - approve is for the exact amount, never unlimited;
 *   - every deposit and redeem is first run as eth_call from the wallet's address: a revert is shown with its reason, nothing is sent;
 *   - this page never holds the money: it goes from the wallet straight into the curator's Morpho Vault V2 contract and back.
 */
(function () {
  'use strict';
  var V = (window.EARN_VAULTS || []).map(function (v) { return Object.assign({}, v, { a: String(v.a).toLowerCase() }); });
  var SEEN = (window.EARN_SEEN || []).map(function (v) { return Object.assign({}, v, { a: String(v.a).toLowerCase() }); }).filter(function (s) { return !V.some(function (v) { return v.a === s.a; }); });
  var ALL = V.concat(SEEN);           // positions and withdrawals: every USDC vault we ever verified, so a vault that leaves the board stays reachable
  var ON = window.EARN_ON === true;
  var GAS_RESERVE = 50000n;           // 0.05 USDC kept back: on Arc the USDC you deposit is also what pays the two transactions
  var USDC = '0x3600000000000000000000000000000000000000';
  var CHAIN = '0x13b2';
  var RPCS = ['https://rpc.blockdaemon.mainnet.arc.io', 'https://rpc.mainnet.arc.io', 'https://rpc.beamrpc.com'];
  var EXPLORER = 'https://explorer.arc.io/tx/';

  function rpc(m, p, i) {
    i = i || 0;
    return fetch(RPCS[i], { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: m, params: p }) })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (j.error) { var e = new Error(j.error.message || 'rpc error'); e.revert = /revert|execution/i.test(e.message) || j.error.code === 3; throw e; } return j.result; })
      .catch(function (e) { if (e.revert || i + 1 >= RPCS.length) throw e; return rpc(m, p, i + 1); });
  }
  function hex(n) { return BigInt(n).toString(16).padStart(64, '0'); }
  function pad(a) { return String(a).replace(/^0x/, '').toLowerCase().padStart(64, '0'); }
  var ENC = {
    approve: function (spender, amt) { return '0x095ea7b3' + pad(spender) + hex(amt); },
    allowance: function (owner, spender) { return '0xdd62ed3e' + pad(owner) + pad(spender); },
    balanceOf: function (owner) { return '0x70a08231' + pad(owner); },
    deposit: function (amt, receiver) { return '0x6e553f65' + hex(amt) + pad(receiver); },
    redeem: function (shares, receiver, owner) { return '0xba087652' + hex(shares) + pad(receiver) + pad(owner); },
    convertToAssets: function (shares) { return '0x07a2d13a' + hex(shares); }
  };
  // "1.5" -> 1500000n (USDC has 6 decimals). Anything else is refused, never guessed.
  function toUnits(s) {
    var m = String(s == null ? '' : s).trim().match(/^(\d{1,12})(?:\.(\d{0,6}))?$/);
    if (!m) return null;
    return BigInt(m[1]) * 1000000n + BigInt((m[2] || '').padEnd(6, '0') || '0');
  }
  function fmt(u) { var s = BigInt(u).toString().padStart(7, '0'); return s.slice(0, -6) + '.' + s.slice(-6); }
  function call(to, data, from) { var o = { to: to, data: data }; if (from) o.from = from; return rpc('eth_call', [o, 'latest']); }
  function esc(t) { return String(t == null ? '' : t).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function vault(a) { a = String(a || '').toLowerCase(); for (var i = 0; i < V.length; i++) if (V[i].a === a) return V[i]; return null; }
  function anyVault(a) { a = String(a || '').toLowerCase(); for (var i = 0; i < ALL.length; i++) if (ALL[i].a === a) return ALL[i]; return null; }
  function provider() {
    var w = window, e = w.ethereum;
    var c = [w.bitkeep && w.bitkeep.ethereum, w.bitget && w.bitget.ethereum, e && e.providers && e.providers.length ? (e.providers.find(function (p) { return p.isMetaMask; }) || e.providers[0]) : e, w.okxwallet, w.trustwallet && w.trustwallet.ethereum];
    for (var i = 0; i < c.length; i++) if (c[i] && typeof c[i].request === 'function') return c[i];
    return null;
  }
  function reason(e) { var m = String((e && e.message) || e); if ((e && e.code === 4001) || /reject|denied|cancel/i.test(m)) return 'Cancelled in the wallet. Nothing was sent.'; return m.slice(0, 200); }

  var eth = null, me = null;
  function connect() {
    if (me) return Promise.resolve(me);
    eth = provider();
    if (!eth) return Promise.reject(new Error('No wallet in this browser. Open this page inside a wallet app (MetaMask, Rabby, Bitget, Coinbase Wallet).'));
    return eth.request({ method: 'eth_requestAccounts' }).then(function (acc) {
      var a = acc && acc[0];
      if (!/^0x[0-9a-fA-F]{40}$/.test(a || '')) throw new Error('your wallet gave no address');
      me = a.toLowerCase();
      if (eth.on && !eth.__apexEarn) { eth.__apexEarn = true; eth.on('accountsChanged', function () { me = null; var w2 = document.getElementById('earnme'); if (w2) w2.textContent = ''; }); }
      var w = document.getElementById('earnme'); if (w) w.textContent = 'Wallet ' + me.slice(0, 6) + '…' + me.slice(-4) + ': deposits and withdrawals go to and from this address only.';
      return me;
    });
  }
  function onArc() {
    return eth.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: CHAIN }] }).catch(function (e) {
      if (e && (e.code === 4902 || /unrecognized|not added|unknown chain/i.test(e.message || ''))) {
        return eth.request({ method: 'wallet_addEthereumChain', params: [{ chainId: CHAIN, chainName: 'Arc', nativeCurrency: { name: 'USDC', symbol: 'USDC', decimals: 18 }, rpcUrls: ['https://rpc.mainnet.arc.io'], blockExplorerUrls: ['https://explorer.arc.io'] }] });
      }
      throw e;
    });
  }
  function receipt(hash) {
    var tries = 0;
    return new Promise(function (ok, bad) {
      (function poll() {
        rpc('eth_getTransactionReceipt', [hash]).then(function (r) {
          if (r && r.status) return r.status === '0x1' ? ok(r) : bad(new Error('the transaction failed on chain: ' + hash));
          if (++tries > 45) return bad(new Error('not confirmed after 90 s; check it on the explorer: ' + hash));
          setTimeout(poll, 2000);
        }).catch(function () { if (++tries > 45) return bad(new Error('could not read the receipt; check the explorer: ' + hash)); setTimeout(poll, 2000); });
      })();
    });
  }
  // The address shown is the only one we send from: re-read it right before every send and stop if the wallet switched.
  function send(to, data) {
    return eth.request({ method: 'eth_accounts' }).then(function (acc) {
      var a = String((acc && acc[0]) || '').toLowerCase();
      if (a !== me) { me = null; var w = document.getElementById('earnme'); if (w) w.textContent = ''; throw new Error('Your wallet switched accounts. Nothing was sent; press the button again to use the new account.'); }
      return eth.request({ method: 'eth_sendTransaction', params: [{ from: me, to: to, data: data }] });
    });
  }

  // ── deposit ─────────────────────────────────────────────────────────────────────────────────────────────
  var panel = document.getElementById('dep'), sel = null;
  function openDeposit(a) {
    var v = vault(a); if (!v || !panel) return;
    sel = v;
    panel.style.display = 'block';
    panel.querySelector('.dv').innerHTML = '<b>' + esc(v.n) + '</b> <span class="soft">(' + esc(v.c || '') + ')</span><br>Rate ' + (v.apy != null ? (v.apy * 100).toFixed(2) + '% (Circle’s figure, not a promise)' : 'unknown') +
      ' · can be taken out right now: <b>$' + Math.round(v.out || 0).toLocaleString('en-US') + '</b>' + (v.warn && v.warn.length ? '<br><b>Circle warns:</b> ' + esc(v.warn.join(', ')) : '') + (v.verdict && v.verdict !== 'LIQUID' ? '<br><b>State ' + esc(v.verdict) + ':</b> most of this vault is lent out, so your money may not come back the moment you ask.' : '');
    panel.querySelector('.dmsg').textContent = '';
    panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  function msg(t, html) { var m = panel.querySelector('.dmsg'); if (html) m.innerHTML = t; else m.textContent = t; }
  function doDeposit() {
    var v = sel; if (!ON || !v || !vault(v.a)) return;
    var amt = toUnits(panel.querySelector('.damt').value);
    if (amt == null || amt <= 0n) { msg('Type an amount in USDC, for example 5 or 2.5.'); return; }
    // What can come out of this vault right now (read on chain every 15 minutes) is the ceiling: a deposit above it would be stuck
    // until borrowers repay, so it is refused and the largest amount that would pass is named (CLAUDE.md 10).
    var outUnits = BigInt(Math.floor((v.out || 0) * 1e6));
    if (amt > outUnits) { msg('Refused: only $' + fmt(outUnits) + ' can come out of ' + v.n + ' right now, so a larger deposit would be stuck until its borrowers repay. Largest amount that passes: ' + fmt(outUnits) + ' USDC. The vault is not bad; its money is lent out.'); return; }
    var go = panel.querySelector('.dgo'); go.disabled = true;
    connect().then(onArc).then(function () { return call(USDC, ENC.balanceOf(me)); }).then(function (b) {
      var bal = BigInt(b);
      if (bal < amt + GAS_RESERVE) throw new Error('This wallet holds ' + fmt(bal) + ' USDC on Arc. A deposit of ' + fmt(amt) + ' needs ' + fmt(amt + GAS_RESERVE) + ': the amount plus 0.05 kept for gas (on Arc, gas is paid in USDC). Largest deposit now: ' + fmt(bal > GAS_RESERVE ? bal - GAS_RESERVE : 0n) + ' USDC.');
      if (amt * 10n > outUnits) msg('Note: this is more than a tenth of what ' + v.n + ' can pay out right now ($' + fmt(outUnits) + '). It can come back, but a busy day could make you wait.');
      return call(USDC, ENC.allowance(me, v.a));
    }).then(function (al) {
      if (BigInt(al) >= amt) return null;
      msg('Step 1 of 2: allow the vault to take exactly ' + fmt(amt) + ' USDC. Confirm in your wallet…');
      return send(USDC, ENC.approve(v.a, amt)).then(function (h) { msg('Waiting for the approval to land…'); return receipt(h); });
    }).then(function () {
      var data = ENC.deposit(amt, me);
      return call(v.a, data, me).then(function () { return data; }, function (e) { throw new Error('The vault would refuse this deposit: ' + String(e.message || e).slice(0, 140) + '. Nothing was sent.'); });
    }).then(function (data) {
      msg('Step 2 of 2: deposit ' + fmt(amt) + ' USDC into ' + v.n + '. Confirm in your wallet…');
      return send(v.a, data);
    }).then(function (h) {
      msg('Deposit sent, waiting for Arc… <a href="' + EXPLORER + esc(h) + '" target="_blank" rel="noopener">transaction</a>', true);
      return receipt(h).then(function () { msg('Done: ' + fmt(amt) + ' USDC is in ' + esc(v.n) + '. <a href="' + EXPLORER + esc(h) + '" target="_blank" rel="noopener">transaction</a>', true); showPositions(); });
    }).catch(function (e) { msg(reason(e)); }).then(function () { go.disabled = false; });
  }

  // ── positions and withdraw ──────────────────────────────────────────────────────────────────────────────
  var out = document.getElementById('posout');
  function showPositions() {
    if (!out) return;
    out.textContent = 'Asking your wallet for its address…';
    connect().then(function () {
      out.textContent = 'Reading ' + ALL.length + ' vaults…';
      return Promise.all(ALL.map(function (v) {
        return call(v.a, ENC.balanceOf(me)).then(function (s) {
          var sh = BigInt(s); if (sh === 0n) return null;
          return call(v.a, ENC.convertToAssets(sh)).then(function (a) { return { v: v, shares: sh, usdc: BigInt(a) }; });
        });
      }));
    }).then(function (r) {
      var held = r.filter(Boolean);
      if (!held.length) { out.textContent = 'This wallet holds nothing in these vaults.'; return; }
      out.innerHTML = held.map(function (x) {
        return '<div style="margin:4px 0"><b>' + esc(x.v.n) + '</b>: ' + fmt(x.usdc) + ' USDC' + (ON ? ' <button type="button" class="pb wd" data-v="' + x.v.a + '">Withdraw all</button>' : '') + '</div>';
      }).join('') + '<div class="soft" id="wdmsg"></div>';
    }).catch(function (e) { out.textContent = /No wallet/.test(String(e.message)) ? e.message : 'Could not read your positions just now (' + reason(e) + '). That says nothing about your money.'; });
  }
  function withdrawAll(a) {
    var v = anyVault(a); if (!ON || !v) return;
    var m = document.getElementById('wdmsg'); var say = function (t, h) { if (!m) return; if (h) m.innerHTML = t; else m.textContent = t; };
    var shares;
    connect().then(onArc).then(function () { return call(v.a, ENC.balanceOf(me)); }).then(function (s) {
      shares = BigInt(s); if (shares === 0n) throw new Error('Nothing to withdraw from ' + v.n + '.');
      var data = ENC.redeem(shares, me, me);
      return call(v.a, data, me).then(function () { return data; }, function (e) { throw new Error(v.n + ' refused to pay out your whole position right now' + (v.out != null ? ' (about $' + Math.round(v.out).toLocaleString('en-US') + ' could come out of the vault at the last check)' : '') + '. The vault said: ' + String((e && e.message) || e).slice(0, 120) + '. Nothing was sent; try again later.'); });
    }).then(function (data) { say('Confirm the withdrawal in your wallet…'); return send(v.a, data); })
      .then(function (h) { say('Withdrawal sent, waiting for Arc…'); return receipt(h).then(function () { say('Done: withdrawn from ' + esc(v.n) + '. <a href="' + EXPLORER + esc(h) + '" target="_blank" rel="noopener">transaction</a>', true); setTimeout(showPositions, 1500); }); })
      .catch(function (e) { say(reason(e)); });
  }

  document.addEventListener('click', function (ev) {
    var t = ev.target; if (!t || !t.closest) return;
    var d = t.closest('button.dep'); if (d && ON) { openDeposit(d.getAttribute('data-v')); return; }
    var w = t.closest('button.wd'); if (w && ON) { withdrawAll(w.getAttribute('data-v')); return; }
    if (t.closest('#posgo')) { showPositions(); return; }
    if (t.closest('.dgo')) { doDeposit(); return; }
    if (t.closest('.dmax')) { connect().then(function () { return call(USDC, ENC.balanceOf(me)); }).then(function (b) { var bal = BigInt(b), m = bal > GAS_RESERVE ? bal - GAS_RESERVE : 0n, cap = sel ? BigInt(Math.floor((sel.out || 0) * 1e6)) : m; panel.querySelector('.damt').value = fmt(m < cap ? m : cap); }).catch(function (e) { msg(reason(e)); }); }
  });
  window.ApexEarn = { ENC: ENC, toUnits: toUnits, fmt: fmt };
})();
